__global__ void grouped_pointer_table_kernel(
        float* output,
        int64_t* pointers,
        int batch,
        int n,
        int block,
        int panels) {
    const int index = static_cast<int>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int count = panels * 2 * batch;
    if (index >= count) {
        return;
    }
    const int matrix = index % batch;
    const int table = index / batch;
    const int kind = table & 1;
    const int panel = table >> 1;
    const int start = panel * block;
    const int stop = min(start + block, n);
    const int64_t matrix_base = static_cast<int64_t>(matrix) * n * n;
    const int64_t element = kind == 0
        ? matrix_base + static_cast<int64_t>(start) * (n + 1)
        : matrix_base + static_cast<int64_t>(start) * n + stop;
    pointers[index] = reinterpret_cast<int64_t>(output + element);
}

torch::Tensor grouped_pointer_table_cuda(
        torch::Tensor output, int64_t block_size) {
    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat,
                "CUDA FP32 output required");
    TORCH_CHECK(output.dim() == 3 && output.size(1) == output.size(2) &&
                output.is_contiguous(), "contiguous square batches required");
    const int batch = static_cast<int>(output.size(0));
    const int n = static_cast<int>(output.size(1));
    const int block = static_cast<int>(block_size);
    TORCH_CHECK(block > 0 && block <= n, "invalid block size");
    const int panels = (n + block - 1) / block;
    auto pointers = torch::empty(
        {panels, 2, batch}, output.options().dtype(at::kLong));
    const int count = panels * 2 * batch;
    grouped_pointer_table_kernel<<<
        (count + 127) / 128, 128, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            output.data_ptr<float>(), pointers.data_ptr<int64_t>(),
            batch, n, block, panels);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return pointers;
}

template <int N>
__global__ void fused_left_looking_tile(
    const float* __restrict__ input,
    float* __restrict__ output
) {
    constexpr int LD = N + 1;
    extern __shared__ float tile[];
    const int tid = threadIdx.x;
    const long long base = static_cast<long long>(blockIdx.x) * N * N;
    const float* src = input + base;
    float* dst = output + base;

    for (int index = tid; index < N * N; index += blockDim.x) {
        const int row = index / N;
        const int col = index - row * N;
        tile[row * LD + col] = row >= col ? src[index] : 0.0f;
    }
    __syncthreads();

    for (int k = 0; k < N; ++k) {
        if (tid == 0) {
            float diagonal = tile[k * LD + k];
            for (int j = 0; j < k; ++j) {
                const float value = tile[k * LD + j];
                diagonal = fmaf(-value, value, diagonal);
            }
            tile[k * LD + k] = sqrtf(fmaxf(diagonal, 1.0e-30f));
        }
        __syncthreads();

        const float diagonal = tile[k * LD + k];
        for (int row = k + 1 + tid; row < N; row += blockDim.x) {
            float value = tile[row * LD + k];
            for (int j = 0; j < k; ++j) {
                value = fmaf(-tile[row * LD + j], tile[k * LD + j], value);
            }
            tile[row * LD + k] = value / diagonal;
        }
        __syncthreads();
    }

    for (int index = tid; index < N * N; index += blockDim.x) {
        const int row = index / N;
        const int col = index - row * N;
        dst[index] = tile[row * LD + col];
    }
}

template <int K>
__device__ __forceinline__ void register_cholesky_step_32(
    float (&row_values)[32],
    int lane
) {
    float value = row_values[K];
    #pragma unroll
    float* tile = storage + group * N * LD;

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        const float* src = input + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            tile[row * LD + lane] = row >= lane
                ? src[row * N + lane]
                : 0.0f;
        }
    }
    __syncthreads();

    float row_values[N];
    #pragma unroll
    for (int col = 0; col < N; ++col) {
        row_values[col] = active ? tile[lane * LD + col] : 0.0f;
    }
    register_cholesky_step_64<0>(
        row_values, tile, inverse, group, lane, active
    );

    if (active) {
        const long long base = static_cast<long long>(matrix) * N * N;
        float* dst = output + base;
        #pragma unroll
        for (int row = 0; row < N; ++row) {
            dst[row * N + lane] = tile[row * LD + lane];
        }
    }
}

__device__ __forceinline__ void factor_panel_16_warp(
    float* tile,
    int panel,
    int lane_base = 0
) {
    constexpr int N = 128;
    const int lane = threadIdx.x % 32;
    const int panel_lane = lane - lane_base;
    const uint32_t panel_mask = 0x0000ffffu << lane_base;
    __syncwarp(0xffffffff);
    if (panel_lane >= 0 && panel_lane < 16) {
        float row_values[16];
        #pragma unroll
        for (int col = 0; col < 16; ++col) {
            row_values[col] = panel_lane >= col
                ? tile[(panel + panel_lane) * N + panel + col]
                : 0.0f;
        }

        #pragma unroll
        for (int pivot = 0; pivot < 16; ++pivot) {
            float value = row_values[pivot];
            #pragma unroll
            for (int col = 0; col < pivot; ++col) {
                const float pivot_value = __shfl_sync(
                    panel_mask, row_values[col], lane_base + pivot
                );
                if (panel_lane >= pivot) {
                    value = fmaf(-row_values[col], pivot_value, value);
                }
            }
            float inverse = 0.0f;
            if (panel_lane == pivot) {
                const float diagonal = sqrtf(fmaxf(value, 1.0e-30f));
                row_values[pivot] = diagonal;
                inverse = 1.0f / diagonal;
            }
            inverse = __shfl_sync(
                panel_mask, inverse, lane_base + pivot
            );
            if (panel_lane > pivot) {
                row_values[pivot] = value * inverse;
            }
        }

        #pragma unroll
        for (int col = 0; col < 16; ++col) {
            if (panel_lane >= col) {
                tile[(panel + panel_lane) * N + panel + col] =
                    row_values[col];
            }
        }
    }
    __syncwarp(0xffffffff);
}

__device__ __forceinline__ void factor_panel_16(
    float* tile,
    int panel
) {
    if (threadIdx.x / 32 == 0) {
        factor_panel_16_warp(tile, panel);
    }
    __syncthreads();
}

__device__ __forceinline__ void solve_panel_16(
    float* tile,
    int panel
) {
    constexpr int N = 128;
    constexpr int TEAM_WIDTH = 4;
    const int team = threadIdx.x / TEAM_WIDTH;
    const int lane = threadIdx.x % TEAM_WIDTH;
    const int stop = panel + 16;
    const int row = stop + team;
    const bool active = row < N;
    float row_values[4];
    #pragma unroll
    for (int item = 0; item < 4; ++item) {
        row_values[item] = active
            ? tile[row * N + panel + item * TEAM_WIDTH + lane]
            : 0.0f;
    }
    #pragma unroll
    for (int pivot = 0; pivot < 16; ++pivot) {
        float dot = 0.0f;
        #pragma unroll
        for (int item = 0; item < 4; ++item) {
            const int col = item * TEAM_WIDTH + lane;
            if (col < pivot) {
                dot = fmaf(
                    row_values[item],
                    tile[(panel + pivot) * N + panel + col],
                    dot
                );
            }
        }
        dot += __shfl_down_sync(0xffffffff, dot, 2, TEAM_WIDTH);
        dot += __shfl_down_sync(0xffffffff, dot, 1, TEAM_WIDTH);
        float original = __shfl_sync(
            0xffffffff,
            row_values[pivot / TEAM_WIDTH],
            pivot % TEAM_WIDTH,
            TEAM_WIDTH
        );
        float solved = lane == 0
            ? (original - dot)
                / tile[(panel + pivot) * N + panel + pivot]
            : 0.0f;
        solved = __shfl_sync(0xffffffff, solved, 0, TEAM_WIDTH);
        if (lane == pivot % TEAM_WIDTH) {
            row_values[pivot / TEAM_WIDTH] = solved;
        }
    }
    if (active) {
        #pragma unroll
        for (int item = 0; item < 4; ++item) {
            tile[row * N + panel + item * TEAM_WIDTH + lane] =
                row_values[item];
        }
    }
    __syncthreads();
}

__device__ __forceinline__ uint64_t tcgen05_smem_descriptor(
    const float* pointer
) {
    const uint64_t address = static_cast<uint64_t>(
        __cvta_generic_to_shared(pointer)
    );
    return ((address >> 4) & 0x3fffull)
        | (128ull << 16)
        | (8ull << 32)
        | (1ull << 46);
}

__device__ __forceinline__ void compensated_rankk_16_tcgen05(
    float* tile,
    float* high_buffer,
    float* scaled_buffer,
    uint32_t tmem_base,
    uint64_t* mma_barrier,
    int barrier_phase,
    int panel
) {
    constexpr int N = 128;
    constexpr float RESIDUAL_SCALE = 32.0f;
    constexpr float INVERSE_RESIDUAL_SCALE = 1.0f / RESIDUAL_SCALE;
    const int tid = threadIdx.x;
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int stop = panel + 16;
    const int trailing = N - stop;

    for (int logical = tid; logical < trailing * 16;
         logical += blockDim.x) {
        const int row = stop + logical / 16;
        const int k = logical % 16;
        const int physical = (k / 8) * 1024
            + ((k & 7) / 4) * 512 + row * 4 + (k & 3);
        const float original = tile[row * N + panel + k];
        const float high = wmma::__float_to_tf32(original);
        high_buffer[physical] = high;
        scaled_buffer[physical] = wmma::__float_to_tf32(
            fmaf(RESIDUAL_SCALE, original - high, high)
        );
    }
    asm volatile("fence.proxy.async.shared::cta;" : : : "memory");
    __syncthreads();

    const uint64_t high_descriptor_0 =
        tcgen05_smem_descriptor(high_buffer);
    const uint64_t high_descriptor_1 =
        tcgen05_smem_descriptor(high_buffer + 1024);
    const uint64_t high_b_descriptor_0 =
        tcgen05_smem_descriptor(high_buffer + stop * 4);
    const uint64_t high_b_descriptor_1 =
        tcgen05_smem_descriptor(high_buffer + 1024 + stop * 4);
    const uint64_t scaled_descriptor_0 =
        tcgen05_smem_descriptor(scaled_buffer);
    const uint64_t scaled_descriptor_1 =
        tcgen05_smem_descriptor(scaled_buffer + 1024);
    const uint64_t scaled_b_descriptor_0 =
        tcgen05_smem_descriptor(scaled_buffer + stop * 4);
    const uint64_t scaled_b_descriptor_1 =
        tcgen05_smem_descriptor(scaled_buffer + 1024 + stop * 4);
    const uint32_t instruction_descriptor =
        (1u << 4) | (2u << 7) | (2u << 10)
        | ((trailing / 8) << 17) | (8u << 24);

    if (tid == 0) {
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_0, high_b_descriptor_0,
            instruction_descriptor, false
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_1, high_b_descriptor_1,
            instruction_descriptor, true
        );
